import{_ as e,o as l,c as a,a0 as C}from"./chunks/framework.DqMqoJl9.js";const n=JSON.parse('{"title":"Wyler 常数的  群论分解与 CQM 框架嵌入","description":"","frontmatter":{},"headers":[],"relativePath":"D021_Wyler常数.md","filePath":"D021_Wyler常数.md"}'),r={name:"D021_Wyler常数.md"};function M(i,t,L,D,E,H){return l(),a("div",null,[...t[0]||(t[0]=[C('<div><h1 id="wyler-常数的-群论分解与-cqm-框架嵌入" tabindex="-1">Wyler 常数的 $A_4$ 群论分解与 CQM 框架嵌入 <a class="header-anchor" href="#wyler-常数的-群论分解与-cqm-框架嵌入" aria-label="Permalink to &quot;Wyler 常数的 $A_4$ 群论分解与 CQM 框架嵌入&quot;">​</a></h1><p>**作者**：ruster</p><blockquote><p>**定位**：本文为前沿研究记录。文中全部偏差数值属**构造后验数字校验，待独立复现**；按 README 口径，Wyler 式本身在实验精度内，未提供超出实验的新信息。</p></blockquote><blockquote><p>**核心发现**：Wyler 常数（1969）可完全用 $A_4$ 嘉当矩阵的群论不变量表达，偏差达 **0.61 ppm**（构造后验数字校验，待独立复现），与 CQM 粗略表达式 $16384\\pi/375$（偏差 ≈0.162%，1622 ppm）的偏差之比约 **2659**——该比值是 ppm 的相对精度之比，不构成独立精度证据。它是 GL(5) 整体结构比粗略表达式更精确的刻画，自然嵌入 CQM 的 SU(5) 重组实现链条。</p></blockquote><hr><h2 id="_1-wyler-常数的定义" tabindex="-1">1. Wyler 常数的定义 <a class="header-anchor" href="#_1-wyler-常数的定义" aria-label="Permalink to &quot;1. Wyler 常数的定义&quot;">​</a></h2><p>Wyler 常数（Wyler 1969, 1971）定义为：</p><p>$$\\alpha_W = \\frac{9}{8\\pi^4}\\left(\\frac{\\pi^5}{2^4 \\cdot 5!}\\right)^{1/4}$$</p><p>数值：</p><p>$$\\alpha_W = 0.00729734813\\ldots = \\frac{1}{137.0360824\\ldots}$$</p><p>与精细结构常数实验值（CODATA 2018）比较：</p><table tabindex="0"><thead><tr><th style="text-align:left;">量</th><th style="text-align:left;">值</th><th style="text-align:left;">偏差</th></tr></thead><tbody><tr><td style="text-align:left;">$\\alpha_W^{-1}$</td><td style="text-align:left;">$137.0360824$</td><td style="text-align:left;">**0.61 ppm**</td></tr><tr><td style="text-align:left;">$\\alpha_{\\text{CQM}}^{-1} = 16384\\pi/375$</td><td style="text-align:left;">$137.2582774$</td><td style="text-align:left;">1622 ppm</td></tr><tr><td style="text-align:left;">$\\alpha_{\\text{exp}}^{-1}$</td><td style="text-align:left;">$137.035999084$</td><td style="text-align:left;">—</td></tr></tbody></table><p>两者偏差（ppm）之比约 **2659**（相对精度之比，不构成独立精度证据）。</p><hr><h2 id="_2-核心定理-群论分解" tabindex="-1">2. 核心定理：$A_4$ 群论分解 <a class="header-anchor" href="#_2-核心定理-群论分解" aria-label="Permalink to &quot;2. 核心定理：$A_4$ 群论分解&quot;">​</a></h2><h3 id="定理-2-1-wyler-常数的群论分解" tabindex="-1">定理 2.1（Wyler 常数的群论分解） <a class="header-anchor" href="#定理-2-1-wyler-常数的群论分解" aria-label="Permalink to &quot;定理 2.1（Wyler 常数的群论分解）&quot;">​</a></h3><p>Wyler 常数可以精确表示为 $A_4$ 嘉当矩阵的基本群论不变量的组合：</p><p>$$\\boxed{\\alpha_W = \\frac{2h-1}{\\text{tr}(A_4)} \\cdot \\pi^{-r} \\cdot \\left(\\frac{\\pi^h}{2^r \\cdot |W(A_4)|}\\right)^{1/r}}$$</p><p>其中：</p><table tabindex="0"><thead><tr><th style="text-align:left;">符号</th><th style="text-align:left;">值</th><th style="text-align:left;">群论含义</th></tr></thead><tbody><tr><td style="text-align:left;">$h$</td><td style="text-align:left;">5</td><td style="text-align:left;">$A_4$ 的 Coxeter 数</td></tr><tr><td style="text-align:left;">$r$</td><td style="text-align:left;">4</td><td style="text-align:left;">$A_4$ 的秩</td></tr><tr><td style="text-align:left;">$\\lvert W(A_4)\\rvert$</td><td style="text-align:left;">120</td><td style="text-align:left;">Weyl 群阶 $= (r+1)! = 5!$</td></tr><tr><td style="text-align:left;">$\\text{tr}(A_4)$</td><td style="text-align:left;">8</td><td style="text-align:left;">嘉当矩阵迹 $= 2r$</td></tr><tr><td style="text-align:left;">$2h-1$</td><td style="text-align:left;">9</td><td style="text-align:left;">Coxeter 数的线性组合</td></tr></tbody></table><h3 id="证明" tabindex="-1">证明 <a class="header-anchor" href="#证明" aria-label="Permalink to &quot;证明&quot;">​</a></h3><p>代入各值：</p><p>$$\\alpha_W = \\frac{2\\times 5 - 1}{8} \\cdot \\pi^{-4} \\cdot \\left(\\frac{\\pi^5}{2^4 \\cdot 5!}\\right)^{1/4} = \\frac{9}{8\\pi^4}\\left(\\frac{\\pi^5}{16 \\cdot 120}\\right)^{1/4}$$</p><p>与 Wyler 常数的定义完全一致。本定理为代数恒等式的改写与群论不变量的重新标注，非物理推导。$\\blacksquare$</p><h3 id="推论-2-2-4-次方形式" tabindex="-1">推论 2.2（4 次方形式） <a class="header-anchor" href="#推论-2-2-4-次方形式" aria-label="Permalink to &quot;推论 2.2（4 次方形式）&quot;">​</a></h3><p>$$\\alpha_W^{-4} = \\frac{2^{16}}{3^8} \\cdot \\pi^{11} \\cdot 5!$$</p><p>其中指数 11 有两种自然群论解释：</p><ul><li>$11 = 2h + 1 = 2 \\times 5 + 1$</li><li>$11 = \\dim(\\text{SU}(5))/2 - 1 = 24/2 - 1$</li></ul><hr><h2 id="_3-各部分的群论-物理含义与-cqm-对应" tabindex="-1">3. 各部分的群论-物理含义与 CQM 对应 <a class="header-anchor" href="#_3-各部分的群论-物理含义与-cqm-对应" aria-label="Permalink to &quot;3. 各部分的群论-物理含义与 CQM 对应&quot;">​</a></h2><p>Wyler 常数的每一因子都是 $A_4$ 的精确群论不变量，在 CQM 框架中均有明确角色。</p><h3 id="_3-1-coxeter-数" tabindex="-1">3.1 Coxeter 数 $h = 5$ <a class="header-anchor" href="#_3-1-coxeter-数" aria-label="Permalink to &quot;3.1 Coxeter 数 $h = 5$&quot;">​</a></h3><p>$A_4$ 的 Coxeter 数 $h = 5$ 是最核心的群论不变量：</p><ul><li>**CQM 中的角色**：决定 $Z_{\\max} = 118$（元素周期表上限）、$l_{\\max} = h-2 = 3$（无 g 壳层）</li><li>**SU(5) 的 Coxeter 数**：$h = 5$ 同时是 SU(5) 的 Coxeter 数</li><li>**在 Wyler 常数中**：$h$ 出现于 $\\pi^h$（分子）和 $2h-1$（前因子），控制 $\\pi$ 的幂次和整体标度</li></ul><h3 id="_3-2-秩" tabindex="-1">3.2 秩 $r = 4$ <a class="header-anchor" href="#_3-2-秩" aria-label="Permalink to &quot;3.2 秩 $r = 4$&quot;">​</a></h3><p>$A_4$ 的秩 $r = 4$：</p><ul><li>**本征群数量**：4 紧致本征群 = $\\{SU(2)_k\\}_{k=1}^{4}$（全紧致壳层群，对应 s/p/d/f）</li><li>**时空维度**：4 = 秩 = 本征群数量 = 时空维度（数值巧合，非群论对应；规范重组实现给出 $U(1)\\times SU(2)\\times SU(3)$ 三个规范群因子，时间内禀没有群）</li><li>**在 Wyler 常数中**：$r$ 出现于 $\\pi^{-r}$（前因子）和 $1/r$ 次幂（根号），$1/r$ 次幂可能对应 4 维时空体积归一化</li></ul><h3 id="_3-3-weyl-群阶" tabindex="-1">3.3 Weyl 群阶 $|W(A_4)| = 5! = 120$ <a class="header-anchor" href="#_3-3-weyl-群阶" aria-label="Permalink to &quot;3.3 Weyl 群阶 $|W(A_4)| = 5! = 120$&quot;">​</a></h3><p>$A_4$ 的 Weyl 群是 $S_5$（5 个对象的排列群），阶为 $5! = 120$：</p><ul><li>**SU(5) 的 Weyl 群**：$W(\\text{SU}(5)) = S_5$</li><li>**CQM 中的角色**：CQM 大量使用 Weyl 群对称性，$S_5$ 决定 $A_4$ 根系的对称性，进而决定嘉当矩阵的结构</li><li>**在 Wyler 常数中**：$|W|$ 出现于分母 $2^r \\cdot |W|$ 内，反映群对称性对 $\\alpha$ 的约束</li></ul><h3 id="_3-4-嘉当矩阵迹" tabindex="-1">3.4 嘉当矩阵迹 $\\text{tr}(A_4) = 8$ <a class="header-anchor" href="#_3-4-嘉当矩阵迹" aria-label="Permalink to &quot;3.4 嘉当矩阵迹 $\\text{tr}(A_4) = 8$&quot;">​</a></h3><p>$A_4$ 嘉当矩阵为 $4\\times 4$ 矩阵，对角线元素全为 2：</p><p>$$\\text{tr}(A_4) = 2 \\times 4 = 8$$</p><ul><li>**CQM 中的角色**：$A_4$ 嘉当矩阵是 SU(5) 重组实现后禁闭边界涌现的代数结构，其迹对应 4 个壳层本征群 $\\{SU(2)_k\\}_{k=1}^{4}$ 各自 Casimir 值 2 的总和</li><li>**在 Wyler 常数中**：$\\text{tr}(A_4) = 8$ 是前因子分母，$9/8 = (2h-1)/\\text{tr}(A_4)$ 正是 Wyler 常数定义中的前因子</li></ul><h3 id="_3-5-因子" tabindex="-1">3.5 因子 $2h - 1 = 9$ <a class="header-anchor" href="#_3-5-因子" aria-label="Permalink to &quot;3.5 因子 $2h - 1 = 9$&quot;">​</a></h3><p>$$2h - 1 = 2 \\times 5 - 1 = 9$$</p><ul><li>**可能的物理来源**：$9 = 3^2$ 可能与 SU(3) 色群有关；$2h-1$ 可能是某种正则化条件或 Casimir 算符的本征值</li><li>**开放问题**：为什么是 $2h-1$ 出现在分子中，而非其他 Coxeter 数线性组合？</li></ul><hr><h2 id="_4-嵌入-cqm-的-su-5-重组实现框架" tabindex="-1">4. 嵌入 CQM 的 SU(5) 重组实现框架 <a class="header-anchor" href="#_4-嵌入-cqm-的-su-5-重组实现框架" aria-label="Permalink to &quot;4. 嵌入 CQM 的 SU(5) 重组实现框架&quot;">​</a></h2><h3 id="_4-1-su-5-重组实现链条" tabindex="-1">4.1 SU(5) 重组实现链条 <a class="header-anchor" href="#_4-1-su-5-重组实现链条" aria-label="Permalink to &quot;4.1 SU(5) 重组实现链条&quot;">​</a></h3><p>CQM 的核心框架是：</p><p>$$\\text{SU}(5) \\;\\xRightarrow{\\text{重组实现}}\\; A_4 \\;\\xrightarrow{\\text{4本征群}}\\; \\{SU(2)_k\\}_{k=1}^{4}\\text{（全紧致壳层群）} \\;\\xrightarrow{\\text{U(1)耦合常数}}\\; \\alpha$$</p><p>Wyler 常数完全由 $A_4$ 的群论不变量决定，因此自然嵌入这个链条：</p><p>$$\\text{SU}(5) \\;\\xRightarrow{\\text{重组实现}}\\; A_4 \\;\\xrightarrow{\\text{群论不变量 } h, r, |W|, \\text{tr}}\\; \\alpha_W$$</p><p>具体地，Wyler 常数使用了 $A_4$ 的**四个基本群论不变量**：Coxeter 数 $h$、秩 $r$、Weyl 群阶 $|W|$、嘉当矩阵迹 $\\text{tr}(A_4)$，这些都是**精确**的，不是近似。</p><h3 id="_4-2-与粗略表达式-的对比" tabindex="-1">4.2 与粗略表达式 $16384\\pi/375$ 的对比 <a class="header-anchor" href="#_4-2-与粗略表达式-的对比" aria-label="Permalink to &quot;4.2 与粗略表达式 $16384\\pi/375$ 的对比&quot;">​</a></h3><p>CQM 框架中 $\\alpha$ 的两种候选表达式：</p><table tabindex="0"><thead><tr><th style="text-align:left;"></th><th style="text-align:left;">CQM 粗略表达式</th><th style="text-align:left;">Wyler 常数</th></tr></thead><tbody><tr><td style="text-align:left;">表达式</td><td style="text-align:left;">$16384\\pi/375$</td><td style="text-align:left;">$\\frac{2h-1}{\\text{tr}(A_4)} \\pi^{-r} \\left(\\frac{\\pi^h}{2^r \\lvert W\\rvert}\\right)^{1/r}$</td></tr><tr><td style="text-align:left;">使用的群论信息</td><td style="text-align:left;">本征值**近似**比例 $9:4:1$</td><td style="text-align:left;">Coxeter 数、秩、Weyl 群阶、迹（**全部精确**不变量）</td></tr><tr><td style="text-align:left;">信息性质</td><td style="text-align:left;">近似（$\\lambda_4/\\lambda_1 = 3.618/0.382 = 9.472 \\approx 9$，约 5% 误差）</td><td style="text-align:left;">**全部精确**群论不变量</td></tr><tr><td style="text-align:left;">信息完整性</td><td style="text-align:left;">仅用近似比例</td><td style="text-align:left;">用了 $A_4$ 的**全部基本**不变量</td></tr><tr><td style="text-align:left;">精度</td><td style="text-align:left;">1622 ppm</td><td style="text-align:left;">0.61 ppm</td></tr><tr><td style="text-align:left;">性质</td><td style="text-align:left;">GL(5) 整体的**粗略**反映</td><td style="text-align:left;">GL(5) 整体的**精确**反映</td></tr></tbody></table><h3 id="_4-3-精度提高-2659-倍的来源" tabindex="-1">4.3 精度提高 2659 倍的来源 <a class="header-anchor" href="#_4-3-精度提高-2659-倍的来源" aria-label="Permalink to &quot;4.3 精度提高 2659 倍的来源&quot;">​</a></h3><p>CQM 的 $16384\\pi/375$ 来自近似比例 $9:4:1$：</p><p>$$\\frac{\\lambda_4}{\\lambda_1} = \\frac{3.618}{0.382} = 9.472\\ldots \\neq 9$$</p><p>这个近似引入约 5% 误差，传播到 $\\alpha^{-1}$ 后收窄为 1622 ppm。</p><p>Wyler 常数使用 $A_4$ 的**精确**群论不变量（$h = 5$、$r = 4$、$|W| = 120$、$\\text{tr} = 8$），不涉及任何近似，两者偏差之比约 2659 来源于其使用了更完整的群论信息；该比值是相对精度之比，不构成独立精度证据。</p><p>**类比**：</p><ul><li>CQM 粗略表达式：用“本征值的影子”（近似比例）计算 $\\alpha$</li><li>Wyler 常数：用“本征值的完整基因组”（全部精确不变量）计算 $\\alpha$</li></ul><hr><h2 id="_5-对-来源的意义" tabindex="-1">5. 对 $\\alpha$ 来源的意义 <a class="header-anchor" href="#_5-对-来源的意义" aria-label="Permalink to &quot;5. 对 $\\alpha$ 来源的意义&quot;">​</a></h2><h3 id="_5-1-两种候选表达式" tabindex="-1">5.1 两种候选表达式 <a class="header-anchor" href="#_5-1-两种候选表达式" aria-label="Permalink to &quot;5.1 两种候选表达式&quot;">​</a></h3><p>若采纳 Wyler 常数作为 $\\alpha$ 的更精确表达式，则 $\\alpha$ 来源框架变为：</p><p>$$\\text{SU}(5) \\;\\xRightarrow{\\text{重组实现}}\\; A_4 \\;\\xrightarrow{\\text{全部群论不变量}}\\; \\alpha_W = \\frac{2h-1}{\\text{tr}(A_4)} \\pi^{-r} \\left(\\frac{\\pi^h}{2^r |W|}\\right)^{1/r}$$</p><p>这个框架的优美之处：</p><ol><li>**无任意参数**：全部由 $A_4$ 的群论结构决定</li><li>**偏差小**：0.61 ppm（远小于粗略表达式的 1622 ppm；仍高出 $\\alpha$ 的实验不确定度约 3–4 个数量级）</li><li>**与 CQM 完全一致**：SU(5) 重组实现 ⇒ $A_4$ → $\\alpha$</li><li>**Weyl 群自然出现**：$5! = |S_5|$ 是 SU(5) 的 Weyl 群阶</li></ol><h3 id="_5-2-对-gl-5-整体反映-的强化" tabindex="-1">5.2 对“GL(5) 整体反映”的强化 <a class="header-anchor" href="#_5-2-对-gl-5-整体反映-的强化" aria-label="Permalink to &quot;5.2 对“GL(5) 整体反映”的强化&quot;">​</a></h3><p>CQM 断言“$\\alpha$ 是 GL(5) 整体的反映”。Wyler 常数为此断言提供了**更精确的刻画**：</p><ul><li>$16384\\pi/375$ 只用了近似比例 → GL(5) 的**粗略**反映</li><li>Wyler 常数用了 $A_4$ 的**全部**基本群论不变量 → GL(5) 的**精确**反映</li></ul><h3 id="_5-3-采纳后的理论状态" tabindex="-1">5.3 采纳后的理论状态 <a class="header-anchor" href="#_5-3-采纳后的理论状态" aria-label="Permalink to &quot;5.3 采纳后的理论状态&quot;">​</a></h3><ol><li>**$\\alpha$ 表达式**：$\\alpha^{-1} = \\frac{16}{9} \\pi^{11/4} (5!)^{1/4} \\approx 137.0361$（$A_4$ 全部群论不变量 $h=5$、$r=4$、$|W|=120$、$\\text{tr}=8$，0.61 ppm）；SU(5) 启发式近似 $\\alpha^{-1} = 16384\\pi/375 \\approx 137.2583$（≈0.162%）。两者为并列的候选表达式</li><li>**GL(5) 反映定位**：此精确表达式是 GL(5) 整体的反映，使用 $A_4$ 全部群论不变量</li><li>**推导链**：在同步算符 → 本征群 → $\\alpha$ 的末端补充 Wyler 组合的群论推导</li></ol><hr><h2 id="_6-评估与开放问题" tabindex="-1">6. 评估与开放问题 <a class="header-anchor" href="#_6-评估与开放问题" aria-label="Permalink to &quot;6. 评估与开放问题&quot;">​</a></h2><h3 id="_6-1-支持的理由" tabindex="-1">6.1 支持的理由 <a class="header-anchor" href="#_6-1-支持的理由" aria-label="Permalink to &quot;6.1 支持的理由&quot;">​</a></h3><ol><li>**偏差小**：0.61 ppm（构造后验数字校验，待独立复现；Wyler 式本身在实验精度内，巧合论证不构成独立精度证据）</li><li>**群论结构完整**：每一部分都是 $A_4$ 的精确不变量，无任意参数</li><li>**与 CQM 框架完全一致**：SU(5)⇒$A_4$→$\\alpha$，且是 GL(5) 整体更精确的反映</li><li>**Weyl 群 $S_5$ 自然出现**：$5! = 120$ 是 SU(5) Weyl 群阶，CQM 大量使用 Weyl 群对称性</li><li>**$1/4$ 次幂的猜想性来源**：4 = 秩 = 本征群数量 = 时空维度（数值巧合，非群论对应），可能对应 4 维体积归一化</li><li>**与 CQM 粗略表达式同源**：两者都是 GL(5) 整体的反映，Wyler 是更精确的版本</li></ol><h3 id="_6-2-反对的理由" tabindex="-1">6.2 反对的理由 <a class="header-anchor" href="#_6-2-反对的理由" aria-label="Permalink to &quot;6.2 反对的理由&quot;">​</a></h3><ol><li>**Wyler 原始推导的合法性存疑**：Robertson (1971) 指出 Wyler 表达式仅在把相关空间半径**任意取为 1** 时才与实验符合，半径取值的依据未获解释，由此质疑其推导</li><li>**缺乏物理推导链**：虽有群论结构，但缺乏从物理第一性原理到此具体表达式的严格推导</li><li>**$2h-1=9$ 的物理机制不明**：为什么是 $2h-1$ 出现在分子中？</li><li>**$1/r$ 次幂的来源**：为什么是 $1/4$ 次幂？需要体积归一化的物理解释</li><li>**历史评价**：Adler (1972) 称其为“一个寻找理论的数”</li></ol><h3 id="_6-3-结论" tabindex="-1">6.3 结论 <a class="header-anchor" href="#_6-3-结论" aria-label="Permalink to &quot;6.3 结论&quot;">​</a></h3><p>**Wyler 常数与 GL(5)/SU(5) 的关系确实极其紧密**。它完全由 $A_4$ 嘉当矩阵的群论不变量决定，是 GL(5) 整体结构远比 $16384\\pi/375$ 更精确的反映。在 CQM 的 SU(5) 重组实现框架中，Wyler 常数有可能是 $\\alpha$ 的**正确表达式**，而 $16384\\pi/375$ 只是其粗略近似。</p><p>**当前定位**：Wyler 常数是 CQM 框架中 $\\alpha$ 的**候选精确表达式**，与 SU(5) 启发式近似 $16384\\pi/375$ 并列为候选；Wyler 常数纳入 CQM 框架仍**待严格推导**。</p><h3 id="_6-4-开放问题" tabindex="-1">6.4 开放问题 <a class="header-anchor" href="#_6-4-开放问题" aria-label="Permalink to &quot;6.4 开放问题&quot;">​</a></h3><p>要将 Wyler 常数严格纳入 CQM 框架，需解决以下问题：</p><table tabindex="0"><thead><tr><th style="text-align:left;">问题</th><th style="text-align:left;">说明</th><th style="text-align:left;">可能的思路</th></tr></thead><tbody><tr><td style="text-align:left;">**为什么用这种组合？**</td><td style="text-align:left;">为什么 $\\alpha$ 用 $h$、$r$、$\\lvert W\\rvert$ 的这种特定组合表达？</td><td style="text-align:left;">可能对应群论体积或特征值公式；$\\pi^h/\\lvert W\\rvert$ 可能与 SU(5) 对称空间体积有关</td></tr><tr><td style="text-align:left;">**$1/r$ 次幂的物理来源**</td><td style="text-align:left;">为什么是 $1/4$ 次幂？</td><td style="text-align:left;">4 = 时空维度（与秩 $r=4$ 数值巧合），$1/4$ 对应 4 维体积归一化；或与同步算符的谱几何有关</td></tr><tr><td style="text-align:left;">**$2h-1=9$ 的物理机制**</td><td style="text-align:left;">为什么 $2h-1$ 出现在分子中？</td><td style="text-align:left;">$9 = 3^2$ 可能与 SU(3) 色群有关；可能是某种 Casimir 算符本征值或正则化条件</td></tr><tr><td style="text-align:left;">**从 CQM 推导链到 Wyler 常数**</td><td style="text-align:left;">能否从 CQM 严格推导链导出？</td><td style="text-align:left;">在同步算符 → 本征群 → $\\alpha$ 末端补充 Wyler 组合的群论推导</td></tr></tbody></table><p>CQM 现有推导链：</p><p>$$\\text{Regge剖分} \\to [\\hat{X},\\hat{P}]=i\\hbar \\to \\text{嘉当矩阵} \\to \\text{声子} \\to \\text{曲率算符} \\to \\text{FG因果} \\to \\text{耦合动量} \\to \\text{耦合常数算符} \\to \\text{同步算符} \\to \\text{本征群} \\to \\alpha$$</p><p>需要在此链末端解释为什么应该用 Wyler 的特定组合，而非本征值线性组合。</p><hr><h2 id="_7-嘉当矩阵的完整群论数据" tabindex="-1">7. $A_4$ 嘉当矩阵的完整群论数据 <a class="header-anchor" href="#_7-嘉当矩阵的完整群论数据" aria-label="Permalink to &quot;7. $A_4$ 嘉当矩阵的完整群论数据&quot;">​</a></h2><p>供参考，$A_4$ 嘉当矩阵的所有基本群论不变量：</p><h3 id="_7-1-嘉当矩阵" tabindex="-1">7.1 嘉当矩阵 <a class="header-anchor" href="#_7-1-嘉当矩阵" aria-label="Permalink to &quot;7.1 嘉当矩阵&quot;">​</a></h3><p>$$A_4 = \\begin{pmatrix} 2 & -1 & 0 & 0 \\\\ -1 & 2 & -1 & 0 \\\\ 0 & -1 & 2 & -1 \\\\ 0 & 0 & -1 & 2 \\end{pmatrix}$$</p><p>这是 SU(5) 的嘉当矩阵，秩 $r=4$，Coxeter 数 $h=5$，Weyl 群阶 $|W(A_4)|=5!=120$，迹 $\\text{tr}(A_4)=8$。</p><h3 id="_7-2-本征值" tabindex="-1">7.2 本征值 <a class="header-anchor" href="#_7-2-本征值" aria-label="Permalink to &quot;7.2 本征值&quot;">​</a></h3><p>$$\\lambda_k = 2 - 2\\cos\\frac{k\\pi}{5}, \\quad k = 1, 2, 3, 4$$</p><table tabindex="0"><thead><tr><th style="text-align:left;">$k$</th><th style="text-align:left;">$\\lambda_k$</th><th style="text-align:left;">数值</th></tr></thead><tbody><tr><td style="text-align:left;">1</td><td style="text-align:left;">$\\frac{3-\\sqrt{5}}{2}$</td><td style="text-align:left;">0.381966</td></tr><tr><td style="text-align:left;">2</td><td style="text-align:left;">$\\frac{5-\\sqrt{5}}{2}$</td><td style="text-align:left;">1.381966</td></tr><tr><td style="text-align:left;">3</td><td style="text-align:left;">$\\frac{3+\\sqrt{5}}{2}$</td><td style="text-align:left;">2.618034</td></tr><tr><td style="text-align:left;">4</td><td style="text-align:left;">$\\frac{5+\\sqrt{5}}{2}$</td><td style="text-align:left;">3.618034</td></tr></tbody></table><h3 id="_7-3-不变量汇总" tabindex="-1">7.3 不变量汇总 <a class="header-anchor" href="#_7-3-不变量汇总" aria-label="Permalink to &quot;7.3 不变量汇总&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">不变量</th><th style="text-align:left;">值</th><th style="text-align:left;">表达式</th></tr></thead><tbody><tr><td style="text-align:left;">秩 $r$</td><td style="text-align:left;">4</td><td style="text-align:left;">—</td></tr><tr><td style="text-align:left;">Coxeter 数 $h$</td><td style="text-align:left;">5</td><td style="text-align:left;">$= r + 1 = \\det(A_4)$</td></tr><tr><td style="text-align:left;">行列式 $\\det(A_4)$</td><td style="text-align:left;">5</td><td style="text-align:left;">$= h$</td></tr><tr><td style="text-align:left;">迹 $\\text{tr}(A_4)$</td><td style="text-align:left;">8</td><td style="text-align:left;">$= 2r$</td></tr><tr><td style="text-align:left;">迹平方 $\\text{tr}(A_4^2)$</td><td style="text-align:left;">22</td><td style="text-align:left;">—</td></tr><tr><td style="text-align:left;">Weyl 群阶 $\\lvert W\\rvert$</td><td style="text-align:left;">120</td><td style="text-align:left;">$= (r+1)! = 5!$</td></tr><tr><td style="text-align:left;">正根数 $N_+$</td><td style="text-align:left;">10</td><td style="text-align:left;">$= rh/2$</td></tr><tr><td style="text-align:left;">对偶 Coxeter 数 $h^\\vee$</td><td style="text-align:left;">5</td><td style="text-align:left;">$= h$（$A_n$ 型自对偶）</td></tr></tbody></table><hr><h2 id="_8-相关文档" tabindex="-1">8. 相关文档 <a class="header-anchor" href="#_8-相关文档" aria-label="Permalink to &quot;8. 相关文档&quot;">​</a></h2><ul><li><code>01 核心理论/CQM_核心_集成理论.md</code> §7 — CQM 的 $\\alpha$ 推导</li><li><code>07 精细引力（FG）/FG_核心理论.md</code> §5.1.1 — SU(5) 重组实现链条</li></ul><hr><h2 id="_9-参考文献" tabindex="-1">9. 参考文献 <a class="header-anchor" href="#_9-参考文献" aria-label="Permalink to &quot;9. 参考文献&quot;">​</a></h2><ul><li>Wyler, A. “L&#39;espace symétrique du groupe des équations de Maxwell.” *C. R. Acad. Sci. Paris* **269**, A743-A745, 1969.</li><li>Wyler, A. “Les groupes des potentiels de Coulomb et de Yukawa.” *C. R. Acad. Sci. Paris* **271**, 186-188, 1971.</li><li>Robertson, B. “Wyler&#39;s Expression for the Fine-Structure Constant.” *Phys. Rev. Lett.* **27**, 1545-1547, 1971.</li><li>Adler, S. L. “Theories of the Fine Structure Constant.” Fermilab, 1972.</li><li>Gilmore, R. “Scaling of Wyler&#39;s Expression for $\\alpha$.” *Phys. Rev. Lett.* **28**, 462-464, 1972.</li><li>Kragh, H. “Magic Number: A Partial History of Fine-Structure Constant.” *Arch. Hist. Exact Sci.* **57**, 395-431, 2003.</li><li>Weisstein, Eric W. “Wyler&#39;s Constant.” From *MathWorld* — <a href="https://mathworld.wolfram.com/WylersConstant.html" target="_blank" rel="noreferrer">https://mathworld.wolfram.com/WylersConstant.html</a></li></ul></div>',1)])])}const h=e(r,[["render",M]]);export{n as __pageData,h as default};
